<?php require_once __DIR__.'/inc/bootstrap.php'; require_login(); $pageTitle='AJAX event manager'; require __DIR__.'/inc/header.php'; ?>
<div class="page-heading"><div><div class="eyebrow">PRACTICAL 13</div><h1>AJAX event manager</h1><p>Load events from a PHP JSON API without refreshing the page.</p></div><span class="pill">FETCH API</span></div>
<section class="panel"><p id="apiStatus" role="status">Loading events…</p><div id="apiEvents" class="event-grid"></div></section>
<?php if(($_SESSION['role']??'')==='admin'): ?><section class="panel"><h2>Add event using Fetch</h2><form id="apiEventForm" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Title<input required name="title"></label><label>Category<input name="category" value="General"></label><label>Date<input required type="date" name="event_date"></label><label>Location<input required name="location"></label><label>Status<select name="status"><option value="open">Open</option><option value="closed">Closed</option></select></label><label class="full-field">Description<textarea required name="description" rows="3"></textarea></label><div><button class="btn">Add without reload</button></div></form></section><?php endif; ?>
<script>
(async()=>{const box=document.getElementById('apiEvents'),status=document.getElementById('apiStatus');async function load(){status.textContent='Loading…';try{const r=await fetch('api/events.php',{headers:{Accept:'application/json'}});const d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'Could not load events');box.replaceChildren();d.events.forEach(ev=>{const card=document.createElement('article');card.className='event-card';const h=document.createElement('h3');h.textContent=ev.title;const meta=document.createElement('p');meta.textContent=ev.event_date+' · '+ev.location+' · '+ev.status;const desc=document.createElement('p');desc.textContent=ev.description;card.append(h,meta,desc);box.append(card)});status.textContent=d.events.length+' event(s) loaded from JSON API.'}catch(e){status.textContent=e.message}}
const form=document.getElementById('apiEventForm');if(form)form.addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));try{const r=await fetch('api/events.php',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(data)});const d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'Save failed');form.reset();status.textContent=d.message;await load()}catch(err){status.textContent=err.message}});await load()})();
</script>
<?php require __DIR__.'/inc/footer.php'; ?>
